def transform(grid):
    # For every 8-component, draw a bounding box border with the right side open using color 3
    out = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    visited = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 8 and (r, c) not in visited:
                comp = []
                q = [(r, c)]
                visited.add((r, c))
                for qr, qc in q:
                    comp.append((qr, qc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = qr+dr, qc+dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 8 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                min_r = min(p[0] for p in comp) - 2
                max_r = max(p[0] for p in comp) + 2
                min_c = min(p[1] for p in comp) - 2
                max_c = max(p[1] for p in comp) + 2
                for col in range(min_c, max_c + 1):
                    if 0 <= min_r < H and 0 <= col < W: out[min_r][col] = 3
                    if 0 <= max_r < H and 0 <= col < W: out[max_r][col] = 3
                for row in range(min_r, max_r + 1):
                    if 0 <= row < H and 0 <= min_c < W: out[row][min_c] = 3
    return out

def transform(grid):
    # Enclose any non-enclosed component of color 8 with a C-shape of color 3 matching existing C-shape
    out = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    # check each 3x3 block of 8
    for r in range(H - 2):
        for c in range(W - 2):
            if all(grid[r+i][c+j] == 8 for i in range(3) for j in range(3)):
                for i in range(7):
                    out[r - 2 + i][c - 2] = 3
                    out[r - 2][c - 2 + i] = 3
                    out[r + 4][c - 2 + i] = 3
    return out

